        origen = OrigenProyecto.AUTOEVALUACION,
        objetivo = "Aumentar el nivel de formación de los docentes",
        actividades = listOf("Convocatoria de becas", "Convenios con universidades"),
        factores = setOf("F3"),
        estado = EstadoProyecto.PLANIFICADO,
    )
}

