for m in re.finditer(r'<testcase name=\"([^\"]+)\".*?(?:/>|</testcase>)', content, re.S):
    block = m.group(0)
    if '<failure' in block:
        print('FAIL:', m.group(1))
        fm = re.search(r'<failure message=\"([^\"]*)\"', block)
        if fm: print('   ', fm.group(1)[:300])
